"""prices.py  --  model prices used by the cost tab.   >>> YOU DO NOT EDIT THIS FILE <<<

US$ per 1 million tokens. Checked 12 Oct 2026 against the vendors' public price pages and press coverage.
ALWAYS re-check the vendor price page before you quote a client: prices change, and the same model can cost a
different amount on Bedrock, on the vendor's own API, and on Azure. Cache-read = price of input tokens that were
served from the prompt cache (much cheaper).
"""

PRICES_DATE = "12 Oct 2026"

# key -> label, input, output, cache_read, note
MODELS = {
    "nova-micro":  {"label": "Amazon Nova Micro (Bedrock)", "inp": 0.035, "out": 0.14, "cache": 0.00875,
                    "note": "Text only. Our small lab model. Cheapest, weakest at hard reasoning."},
    "nova-lite":   {"label": "Amazon Nova Lite (Bedrock)", "inp": 0.06, "out": 0.24, "cache": 0.015,
                    "note": "Text + image + video. Our 'large' lab model."},
    "nova-pro":    {"label": "Amazon Nova Pro (Bedrock)", "inp": 0.80, "out": 3.20, "cache": 0.20,
                    "note": "Stronger reasoning. 20 times the price of Micro."},
    "haiku-5.5":   {"label": "Claude Haiku 5.5 (Anthropic API)", "inp": 0.10, "out": 0.50, "cache": 0.01,
                    "note": "Price for prompts up to 100k tokens; above 100k every price is 5 times higher. Check the Bedrock price separately."},
    "sonnet-5.5":  {"label": "Claude Sonnet 5.5 (Anthropic API)", "inp": 2.00, "out": 10.00, "cache": 0.10,
                    "note": "Strong all-rounder. Check the Bedrock price separately."},
    "gpt-5.4-mini": {"label": "gpt-5.4-mini (Azure AI Foundry)", "inp": 0.25, "out": 2.00, "cache": 0.025,
                     "note": "APPROXIMATE. Check your Azure price list."},
}

# which price row each lab provider uses when it measures a run
PROVIDER_DEFAULT = {"bedrock": "nova-micro", "azure": "gpt-5.4-mini", "openai": "gpt-5.4-mini", "offline": "nova-micro"}


def key_for(provider, model_id=""):
    m = (model_id or "").lower()
    for k, token in (("nova-micro", "nova-micro"), ("nova-lite", "nova-lite"), ("nova-pro", "nova-pro"),
                     ("haiku-5.5", "haiku-5"), ("sonnet-5.5", "sonnet-5")):
        if token in m:
            return k
    return PROVIDER_DEFAULT.get(provider, "nova-micro")


def cost(key, tokens_in, tokens_out, cached_in=0):
    p = MODELS[key]
    fresh = max(0, tokens_in - cached_in)
    return fresh / 1e6 * p["inp"] + cached_in / 1e6 * p["cache"] + tokens_out / 1e6 * p["out"]
